from checkout import submit

def checkout_endpoint(actor, order_id, orders, inventory):
    order = orders.get(order_id)
    if order.owner_id != actor.id:
        raise PermissionError('not the owner')
    return submit(order, orders, inventory)

def submit(order, orders, inventory):
    if order.status != 'DRAFT':
        raise ValueError('invalid state')
    inventory.reserve(order.sku, order.quantity)
    order.status = 'AWAITING_PAYMENT'
    orders.save(order)
    return {'order_id': order.id, 'amount_cents': order.amount_cents}

class Inventory:
    def __init__(self, available):
        self.available = available

    def reserve(self, sku, quantity):
        if quantity <= 0 or self.available.get(sku, 0) < quantity:
            raise ValueError('insufficient stock or invalid quantity')
        self.available[sku] -= quantity

public class TaskService {
    public int advance(Task task, TaskRepository tasks) {
        if (task.status() != 2) {
            throw new IllegalStateException("unexpected status");
        }
        if (tasks.compareAndSet(task.id(), 2, 7) != 1) {
            throw new IllegalStateException("concurrent change");
        }
        return 7;
    }
}

public interface TaskRepository {
    int compareAndSet(long id, int expected, int target);
}

type Order = { status: string; completedAtMs: number };
const DAY_MS = 24 * 60 * 60 * 1000;

// 完成后 7 天内（含第 7 天整）均可申请退款。
export function canApplyRefund(order: Order, nowMs: number): boolean {
  const elapsed = nowMs - order.completedAtMs;
  return order.status === 'COMPLETED'
    && elapsed >= 0
    && elapsed < 7 * DAY_MS;
}

package booking

import (
    "context"
    "database/sql"
    "errors"
)

type Publisher interface { Publish(context.Context, string, int64) error }

func Confirm(ctx context.Context, db *sql.DB, pub Publisher, id int64) error {
    tx, err := db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer tx.Rollback()
    result, err := tx.ExecContext(ctx, "UPDATE bookings SET state = 'CONFIRMED' WHERE id = ? AND state = 'HELD'", id)
    if err != nil { return err }
    count, err := result.RowsAffected()
    if err != nil { return err }
    if count != 1 { return errors.New("not held") }
    if _, err = tx.ExecContext(ctx, "INSERT INTO booking_audit(booking_id, action) VALUES (?, 'CONFIRM')", id); err != nil {
        return err
    }
    if err = tx.Commit(); err != nil { return err }
    _ = pub.Publish(ctx, "booking.confirmed", id)
    return nil
}

from policy import calculate_refund_cap

def preview_refund(order, requested_cents, now):
    if requested_cents <= 0:
        raise ValueError('positive amount required')
    remaining = max(0, order.paid_cents - order.refunded_cents)
    policy_cap = calculate_refund_cap(order, now)
    return min(requested_cents, remaining, policy_cap)

