type Receipt = { transferId: string };
type Gateway = { pay: (merchantId: string, amountCents: number) => Promise<Receipt> };
const reviewLimitCents = Number(process.env.REVIEW_LIMIT_CENTS ?? '5000');
const completed = new Map<string, Receipt>();

export async function payout(merchantId: string, requestId: string, amountCents: number, gateway: Gateway) {
  const key = JSON.stringify([merchantId, requestId]);
  const cached = completed.get(key);
  if (cached) return cached;
  if (!Number.isInteger(amountCents) || amountCents <= 0) throw new Error('invalid amount');
  if (amountCents > reviewLimitCents) throw new Error('manual review required');
  const receipt = await gateway.pay(merchantId, amountCents);
  completed.set(key, receipt);
  return receipt;
}
